38	void shm_write(char* shmbuf, atomic_long *_available, char* buf, size_t size)
39	{
40	    while (size > 0) {
41	        while(atomic_load_d(_available) != 0);
42	
43	        int sz = size > FIFO_BUF_MAX ? FIFO_BUF_MAX : size;
44	        memcpy(shmbuf, buf, sz);
45	        size -= sz;
46	
47	        atomic_exchange_d(_available, 1);
48	    }
49	}
50	
51	int is_first(echo_shm_vars_t *vars)
52	{
53	    unsigned long my = atomic_exchange_d(&vars->magic_number, MAGIC);
54	    return my != MAGIC;
55	}
56	
57	int main(int argc, char *argv[])
58	{
59	    int mode = 0;
60	    int size = 1;
61	    if(argc > 1) {
62	        size = atol(argv[1]);
63	    }
64	    if(argc > 2) {        
65	        if (strcmp(argv[2], "1") == 0) {
66	            mode = 1;
67	        }
68	    }
69	    
70	    echo_shm_vars_t *vars = (echo_shm_vars_t*) sys_shmpage_get(SHMP_KEY);
71	    if (vars == NULL) {
72	        sys_move_cursor(1, 1);
73	        printf("shmpageget failed!\n");
74	        return -1;
75	    }
76	    
77	    if (is_first(vars)) {
78	        sys_move_cursor(1, 1);
79	        printf("[ECHO RECV SIDE]\n");
80	        sys_net_irq_mode(mode);
81	
82	        atomic_exchange_d(&vars->available, 0);
83	        sys_exec(argv[0], argc, argv, AUTO_CLEANUP_ON_EXIT);
84	        sys_move_cursor(1, 2);
85	        printf("[ECHO TASK] start recv(%d): ", size);
86	
87	        int ret = sys_net_recv(recv_buffer, size * sizeof(EthernetFrame), size, recv_length);
88	        printf("%d\n", ret);
89	        shm_write(vars->fifo_buffer, &vars->available, recv_buffer, size * sizeof(EthernetFrame));
90	        shm_write(vars->fifo_buffer, &vars->available, recv_length, size * sizeof(size_t));
91	    } else {
92	        int print_location = 3;
93	        sys_move_cursor(1, print_location);
94	        printf("[ECHO SEND SIDE]\n");
95	        shm_read(vars->fifo_buffer, &vars->available, recv_buffer, size * sizeof(EthernetFrame));
96	        shm_read(vars->fifo_buffer, &vars->available, recv_length, size * sizeof(size_t));
97	
98	        int send_num = 0;
99	        int i;
100	        char *cur = recv_buffer;
101	        int resp_len = strlen(response);
102	
103	        for (int i = 0; i < size; ++i)
104	        {
105	            sys_move_cursor(1, print_location + 1);
106	            printf("No.%d packet, recv_length[i] = %ld ...\n", i, recv_length[i]);
107	            memcpy(cur + HDR_OFFSET, response, resp_len);
108	
109	            sys_net_send(cur, recv_length[i]);
110	            send_num += 1;
111	            sys_move_cursor(1, print_location + 2);
112	            printf("[ECHO TASK] Echo no.%d packets ...\n", i);
113	            cur += recv_length[i];
114	        }
115	    }
116	
117	    sys_shmpage_dt((void*)vars);
118	
119	    return 0;
120	}
