18	#include <type.h>
19	#include <io.h>
20	#include <csr.h>
21	#include <os/irq.h>
22	#include <stdio.h>
23	#include <plic.h>
24	
25	#define MAX_DEVICES			1024
26	#define MAX_CONTEXTS			15872
27	
28	/*
29	 * Each interrupt source has a priority register associated with it.
30	 * We always hardwire it to one in Linux.
31	 */
32	#define PRIORITY_BASE			0
33	#define     PRIORITY_PER_ID		4
34	
35	/*
36	 * Each hart context has a vector of interrupt enable bits associated with it.
37	 * There's one bit for each interrupt source.
38	 */
39	#define ENABLE_BASE			0x2000
40	#define     ENABLE_PER_HART		0x80
41	
42	/*
43	 * Each hart context has a set of control registers associated with it.  Right
44	 * now there's only two: a source priority threshold over which the hart will
45	 * take an interrupt, and a register to claim interrupts.
46	 */
47	#define CONTEXT_BASE			0x200000
48	#define     CONTEXT_PER_HART		0x1000
49	#define     CONTEXT_THRESHOLD		0x00
50	#define     CONTEXT_CLAIM		0x04
51	
52	static void *plic_regs;
53	
54	struct plic_handler {
55		bool			present;
56		void		*hart_base;
57		void		*enable_base;
58	} plic_handlers;
59	
60	static inline void plic_toggle(struct plic_handler *handler,
61					int hwirq, int enable)
62	{
63		u32 *reg = handler->enable_base + (hwirq / 32) * sizeof(u32);
64		u32 hwirq_mask = 1 << (hwirq % 32);
65	
66		if (enable)
67			writel(readl(reg) | hwirq_mask, reg);
68		else
69			writel(readl(reg) & ~hwirq_mask, reg);
70	}
71	
72	static void plic_irq_unmask(int hwirq)
73	{
74		int enable = 1;
75		writel(enable, plic_regs + PRIORITY_BASE + hwirq * PRIORITY_PER_ID);
76	    struct plic_handler *handler = &plic_handlers;
77	
78	    if (handler->present) plic_toggle(handler, hwirq, enable);
79	}
80	
81	/*
82	static void plic_irq_mask(int hwirq)
83	{
84		int enable = 0;
85		writel(enable, plic_regs + PRIORITY_BASE + hwirq * PRIORITY_PER_ID);
86	    struct plic_handler *handler = &plic_handlers;
87	
88	    if (handler->present) plic_toggle(handler, hwirq, enable);
89	}
90	*/
91	
92	void plic_irq_eoi(int hwirq)
93	{
94		struct plic_handler *handler = &plic_handlers;
95	
96		writel(hwirq, handler->hart_base + CONTEXT_CLAIM);
97	}
98	
99	#define __ASM_STR(x)	#x
100	#define csr_set(csr, val)					\
101	({								\
102		unsigned long __v = (unsigned long)(val);		\
103		__asm__ __volatile__ ("csrs " __ASM_STR(csr) ", %0"	\
104				      : : "rK" (__v)			\
105				      : "memory");			\
106	})
107	
108	#define csr_clear(csr, val)					\
109	({								\
110		unsigned long __v = (unsigned long)(val);		\
111		__asm__ __volatile__ ("csrc " __ASM_STR(csr) ", %0"	\
112				      : : "rK" (__v)			\
113				      : "memory");			\
114	})
115	
116	/*
117	 * Handling an interrupt is a two-step process: first you claim the interrupt
118	 * by reading the claim register, then you complete the interrupt by writing
119	 * that source ID back to the same claim register.  This automatically enables
120	 * and disables the interrupt, so there's nothing else to do.
121	 */
122	void plic_handle_irq(regs_context_t *regs)
123	{
124		struct plic_handler *handler = &plic_handlers;
125		void *claim = handler->hart_base + CONTEXT_CLAIM;
126		int hwirq;
127	
128		csr_clear(sie, SIE_SEIE);
129		while ((hwirq = readl(claim))) {
130				handle_irq(regs, hwirq);
131		}
132		csr_set(sie, SIE_SEIE);
133	}
134	
135	int plic_init(uintptr_t plic_regs_addr, u32 nr_irqs)
136	{
137	    plic_regs = (void *)plic_regs_addr;
138	
139	    struct plic_handler *handler;
140	    int hwirq;
141	    u32 threshold = 0;
142	
143	    handler = &plic_handlers;
144	    if (handler->present) {
145	        printk("handler already present.\n");
146	        threshold = 0xffffffff;
147	        goto done;
148	    }
149	
150	    handler->present     = true;
151	    handler->hart_base   = plic_regs + CONTEXT_BASE;
152	    handler->enable_base = plic_regs + ENABLE_BASE;
153	
154	done:
155	    /* priority must be > threshold to trigger an interrupt */
156	    writel(threshold, handler->hart_base + CONTEXT_THRESHOLD);
157	    for (hwirq = 1; hwirq <= nr_irqs; hwirq++) plic_toggle(handler, hwirq, 1);
158	
159	    // for qemu to interrupt
160	    plic_irq_unmask(33);
161	
162	    return 0;
163	}
