27	/**
28	*
29	* @brief    Perform a 16-bit endian converion.
30	*
31	* @param        Data: 16 bit value to be converted
32	*
33	* @return       16 bit Data with converted endianess
34	*
35	******************************************************************************/
36	static inline u16 Xil_EndianSwap16(u16 Data)
37	{
38	        return (u16) (((Data & 0xFF00U) >> 8U) | ((Data & 0x00FFU) << 8U));
39	}
40	
41	/*****************************************************************************/
42	/**
43	*
44	* @brief    Perform a 32-bit endian converion.
45	*
46	* @param        Data: 32 bit value to be converted
47	*
48	* @return       32 bit data with converted endianess
49	*
50	******************************************************************************/
51	static inline u32 Xil_EndianSwap32(u32 Data)
52	{
53	        u16 LoWord;
54	        u16 HiWord;
55	
56	        /* get each of the half words from the 32 bit word */
57	
58	        LoWord = (u16) (Data & 0x0000FFFFU);
59	        HiWord = (u16) ((Data & 0xFFFF0000U) >> 16U);
60	
61	        /* byte swap each of the 16 bit half words */
62	
63	        LoWord = (((LoWord & 0xFF00U) >> 8U) | ((LoWord & 0x00FFU) << 8U));
64	        HiWord = (((HiWord & 0xFF00U) >> 8U) | ((HiWord & 0x00FFU) << 8U));
65	
66	        /* swap the half words before returning the value */
67	
68	        return ((((u32)LoWord) << (u32)16U) | (u32)HiWord);
69	}
