 26	long do_net_recv(uintptr_t addr, size_t length, int num_packet, size_t* frLength)
 27	{
 28	    // receive packet by calling network driver's function
 29	    // wait until you receive enough packets(`num_packet`).
 30	    if(num_packet > RXBD_CNT){
 31	        return -1;
 32	    }
 33	    recv_transaction = 1;
 34	    enable_sum();
 35	    for(int i = 0; i < num_packet; i++){
 36	        memset(&rx_buffers[i], 0, sizeof(EthernetFrame));
 37	        rx_len[i] = 0;
 38	    }
 39	    EmacPsRecv(&EmacPsInstance, 0, num_packet);
 40	
 41	    if(net_poll_mode == 0){
 42	        EmacPsWaitRecv(&EmacPsInstance, num_packet, rx_len);
 43	        rx_curr = addr;
 44	        rx_tail = 0;
 45	        for(int i = 0; i < num_packet; i++){
 46	            memcpy((uint8_t*)rx_curr, (uint8_t*)&rx_buffers[i], rx_len[i]);
 47	            *(frLength + i) = rx_len[i];
 48	            rx_curr += rx_len[i];
 49	            rx_tail += rx_len[i];
 50	        }
 51	        disable_sum();
 52	        recv_transaction = 0;
 53	        return rx_tail;
 54	    }
 55	    else if(net_poll_mode == 1){
 56	        _addr = get_kva_of(addr, (uintptr_t)current_running[cpu_id]->pgdir);
 57	        _num_packet = num_packet;
 58	        _frLength = (size_t*)get_kva_of((uintptr_t)frLength, (uintptr_t)current_running[cpu_id]->pgdir);
 59	        do_block(&current_running[cpu_id]->list, &net_recv_queue);
 60	        disable_sum();
 61	        return 0;
 62	    }
 63	    else{
 64	        return -1;
 65	    }
 66	}
 67	
 68	void do_net_send(uintptr_t addr, size_t length)
 69	{
 70	    // send all packet
 71	    send_transaction = 1;
 72	    enable_sum();
 73	    memset(&tx_buffer, 0, sizeof(EthernetFrame));
 74	    memcpy((uint8_t*)&tx_buffer, (uint8_t*)addr, length);
 75	    EmacPsSend(&EmacPsInstance, 0, length);
 76	    if(net_poll_mode == 0){        
 77	        EmacPsWaitSend(&EmacPsInstance);
 78	        send_transaction = 0;
 79	    }
 80	    else if(net_poll_mode == 1){        
 81	        do_block(&current_running[cpu_id]->list, &net_send_queue);
 82	    }
 83	    disable_sum();
 84	}
