 86	void do_net_irq_mode(int mode)
 87	{
 88	    // turn on/off network driver's interrupt mode
 89	    if(net_poll_mode != mode){
 90	        assert(recv_transaction == 0);
 91	        assert(send_transaction == 0);
 92	        net_poll_mode = mode;
 93	        if(net_poll_mode == 1){
 94	            XEmacPs_IntEnable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
 95	                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
 96	            XEmacPs_WriteReg(EmacPsInstance.Config.BaseAddress, XEMACPS_IDR_OFFSET, 0);
 97	        }
 98	        else if(net_poll_mode == 0){
 99	            XEmacPs_IntDisable(&EmacPsInstance, (XEMACPS_IXR_TX_ERR_MASK | XEMACPS_IXR_RX_ERR_MASK |
100	                            (u32)XEMACPS_IXR_FRAMERX_MASK | (u32)XEMACPS_IXR_TXCOMPL_MASK));
101	        }
102	    }
103	}

